63	function usePlanContent(planPath: string, config: Config): PlanContentState {
64	  const [version, setVersion] = useState(0);
65	  const [state, setState] = useState<Omit<PlanContentState, 'refresh'>>({
66	    status: PlanStatus.Loading,
67	  });
