74	    let ignore = false;
75	    setState({ status: PlanStatus.Loading });
76	
77	    const load = async () => {
78	      try {
79	        const pathError = await validatePlanPath(
80	          planPath,
81	          config.storage.getPlansDir(),
82	          config.getTargetDir(),
83	        );
84	        if (ignore) return;
85	        if (pathError) {
86	          setState({ status: PlanStatus.Error, error: pathError });
87	          return;
88	        }
89	
90	        const contentError = await validatePlanContent(planPath);
91	        if (ignore) return;
92	        if (contentError) {
93	          setState({ status: PlanStatus.Error, error: contentError });
94	          return;
95	        }
96	
97	        const result = await processSingleFileContent(
98	          planPath,
99	          config.storage.getPlansDir(),
100	          config.getFileSystemService(),
101	        );
102	
103	        if (ignore) return;
104	
105	        if (result.error) {
106	          setState({ status: PlanStatus.Error, error: result.error });
107	          return;
108	        }
109	
110	        if (typeof result.llmContent !== 'string') {
111	          setState({
112	            status: PlanStatus.Error,
113	            error: 'Plan file format not supported (binary or image).',
114	          });
115	          return;
116	        }
117	
118	        const content = result.llmContent;
119	        if (!content) {
120	          setState({ status: PlanStatus.Error, error: 'Plan file is empty.' });
121	          return;
122	        }
123	        setState({ status: PlanStatus.Loaded, content });
