import type React from 'react';
import { useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry to display in the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  matcher?: string;
  sequential?: boolean;
  enabled: boolean;
}

export interface HooksDialogProps {
  /** The hooks to display. */
  hooks: HookEntry[];
  /** Callback invoked when the dialog should close (e.g. Escape pressed). */
  onClose: () => void;
  /**
   * The maximum number of hooks to display at once. When the number of hooks
   * exceeds this value the list becomes scrollable.
   */
  maxVisibleHooks?: number;
}

/**
 * Get a display name for a hook, falling back to the command when no explicit
 * name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * An interactive dialog that displays the configured hooks, grouped by event
 * name, along with their enabled/disabled status and metadata.
 *
 * The dialog is rendered separately from the message stream and is dismissed
 * when the user presses Escape. When the number of hooks exceeds
 * {@link HooksDialogProps.maxVisibleHooks} the list can be scrolled with the
 * up/down arrow keys and scroll indicators are shown.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const total = hooks.length;
  const isScrollable =
    maxVisibleHooks !== undefined && total > maxVisibleHooks;
  const maxOffset = isScrollable ? total - maxVisibleHooks : 0;

  useKeypress(
    (key) => {
      if (key.name === 'escape') {
        onClose();
        return;
      }

      if (!isScrollable) {
        return;
      }

      if (key.name === 'up') {
        setScrollOffset((prev) => Math.max(0, prev - 1));
      } else if (key.name === 'down') {
        setScrollOffset((prev) => Math.min(maxOffset, prev + 1));
      }
    },
    { isActive: true, priority: true },
  );

  // The window of hooks currently visible. When not scrollable, show them all.
  const visibleHooks =
    maxVisibleHooks !== undefined
      ? hooks.slice(scrollOffset, scrollOffset + maxVisibleHooks)
      : hooks;

  const showUpIndicator = isScrollable && scrollOffset > 0;
  const showDownIndicator = isScrollable && scrollOffset < maxOffset;

  // Group the visible hooks by event name for a more organized display.
  const hooksByEvent = visibleHooks.reduce(
    (acc, hook) => {
      if (!acc[hook.eventName]) {
        acc[hook.eventName] = [];
      }
      acc[hook.eventName].push(hook);
      return acc;
    },
    {} as Record<string, HookEntry[]>,
  );

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.default}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {total === 0 ? (
        <Box marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <>
          <Box>
            <Text color={theme.text.secondary}>
              {showUpIndicator ? '▲' : ' '}
            </Text>
          </Box>
          <Box flexDirection="column" paddingLeft={2}>
            {Object.entries(hooksByEvent).map(([eventName, eventHooks]) => (
              <Box key={eventName} flexDirection="column" marginBottom={1}>
                <Text color={theme.text.accent} bold>
                  {eventName}:
                </Text>
                <Box flexDirection="column" paddingLeft={2}>
                  {eventHooks.map((hook, index) => {
                    const hookName = getHookDisplayName(hook);
                    const statusColor = hook.enabled
                      ? theme.status.success
                      : theme.text.secondary;
                    const statusText = hook.enabled ? 'enabled' : 'disabled';

                    return (
                      <Box
                        key={`${eventName}-${index}`}
                        flexDirection="column"
                      >
                        <Box>
                          <Text>
                            <Text color={theme.text.accent}>{hookName}</Text>
                            <Text color={statusColor}>
                              {` [${statusText}]`}
                            </Text>
                          </Text>
                        </Box>
                        <Box paddingLeft={2} flexDirection="column">
                          {hook.config.description && (
                            <Text italic>{hook.config.description}</Text>
                          )}
                          <Text dimColor>
                            Source: {hook.source}
                            {hook.config.name &&
                              hook.config.command &&
                              ` | Command: ${hook.config.command}`}
                            {hook.matcher && ` | Matcher: ${hook.matcher}`}
                            {hook.sequential && ` | Sequential`}
                            {hook.config.timeout &&
                              ` | Timeout: ${hook.config.timeout}s`}
                          </Text>
                        </Box>
                      </Box>
                    );
                  })}
                </Box>
              </Box>
            ))}
          </Box>
          <Box>
            <Text color={theme.text.secondary}>
              {showDownIndicator ? '▼' : ' '}
            </Text>
          </Box>
        </>
      )}

      <Box marginTop={1}>
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text color={theme.text.secondary}>Press Esc to close</Text>
      </Box>
    </Box>
  );
};
